import { useState } from "react";

export function App() {
  const [open, setOpen] = useState(false);
  const [loading, setLoading] = useState(false);
  function load() { setOpen(true); setLoading(true); setTimeout(() => setLoading(false), 120); }
  return (
    <div>
      <button data-testid="load-modal" onClick={load}>Load modal</button>
      {open ? <div data-testid="modal" role="dialog">{loading ? <span data-testid="modal-loading">Loading</span> : <span>Loaded</span>}</div> : null}
    </div>
  );
}
